);

CREATE TABLE appointment_end (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "appointment" TEXT NOT NULL,
  "replacement" TEXT,
  "reason" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, appointment) REFERENCES appointment (tenant, id),
  FOREIGN KEY (tenant, replacement) REFERENCES appointment (tenant, id)
);

CREATE TABLE appointment_reservation (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "appointment" TEXT NOT NULL,
  "reservation" TEXT NOT NULL,
  "next" TEXT,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, appointment) REFERENCES appointment (tenant, id),
  FOREIGN KEY (tenant, reservation) REFERENCES allocation_reservation (tenant, id),
  FOREIGN KEY (tenant, next) REFERENCES appointment_reservation (tenant, id)
);

CREATE TABLE candidate_slot (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "requirement" TEXT NOT NULL,
  "from_" TEXT NOT NULL,
  "until" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, requirement) REFERENCES scheduling_requirement (tenant, id)
);

CREATE TABLE scheduling_need (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "pool" TEXT NOT NULL,
  "calendar" TEXT NOT NULL,
  "quantity" INTEGER NOT NULL,
  "participant" TEXT,
  "next" TEXT,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, pool) REFERENCES allocation_pool (tenant, id),
  FOREIGN KEY (tenant, calendar) REFERENCES availability_calendar_revision (tenant, id),
  FOREIGN KEY (tenant, participant) REFERENCES participation (tenant, id),
  FOREIGN KEY (tenant, next) REFERENCES scheduling_need (tenant, id)
);

CREATE TABLE scheduling_requirement (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "duration_minutes" INTEGER NOT NULL,
  "participants" TEXT NOT NULL,
  "place" TEXT NOT NULL,
  "head" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, participants) REFERENCES participation_set (tenant, id),
  FOREIGN KEY (tenant, place) REFERENCES place (tenant, id),
  FOREIGN KEY (tenant, head) REFERENCES scheduling_need (tenant, id)
);

CREATE TABLE settlement_book (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE settlement_commit (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "book" TEXT NOT NULL,
  "ordinal" INTEGER NOT NULL,
  "previous" TEXT,
  "event" TEXT NOT NULL,
  "source" TEXT,
  "key_" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, book) REFERENCES settlement_book (tenant, id),
  FOREIGN KEY (tenant, previous) REFERENCES settlement_commit (tenant, id),
  FOREIGN KEY (tenant, event) REFERENCES settlement_event (tenant, id),
  FOREIGN KEY (tenant, source) REFERENCES settlement_source (tenant, id)
);

CREATE TABLE settlement_event (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "book" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "head" TEXT NOT NULL,
  "source" TEXT,
  "occurred_at" TEXT NOT NULL,
  "effective_at" TEXT NOT NULL,
  "reversal_of" TEXT,
  "reason" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, book) REFERENCES settlement_book (tenant, id),
  FOREIGN KEY (tenant, head) REFERENCES settlement_line (tenant, id),
  FOREIGN KEY (tenant, source) REFERENCES settlement_source (tenant, id),
  FOREIGN KEY (tenant, reversal_of) REFERENCES settlement_commit (tenant, id)
);

CREATE TABLE settlement_ledger_link (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "publication" TEXT NOT NULL,
  "posting" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, publication) REFERENCES settlement_commit (tenant, id),
  FOREIGN KEY (tenant, posting) REFERENCES posting_group (tenant, id)
);

CREATE TABLE settlement_line (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "book" TEXT NOT NULL,
  "position" TEXT NOT NULL,
  "quantity" INTEGER NOT NULL,
  "next" TEXT,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, book) REFERENCES settlement_book (tenant, id),
  FOREIGN KEY (tenant, position) REFERENCES settlement_position (tenant, id),
  FOREIGN KEY (tenant, next) REFERENCES settlement_line (tenant, id)
);

CREATE TABLE settlement_position (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "book" TEXT NOT NULL,
  "obligation" TEXT NOT NULL,
  "creditor" TEXT NOT NULL,
  "debtor" TEXT NOT NULL,
  "agreement" TEXT,
  "unit" TEXT NOT NULL,
  "ceiling" INTEGER NOT NULL,
  "due_at" TEXT,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, book) REFERENCES settlement_book (tenant, id),
  FOREIGN KEY (tenant, obligation) REFERENCES obligation (tenant, id),
  FOREIGN KEY (tenant, creditor) REFERENCES party (tenant, id),
  FOREIGN KEY (tenant, debtor) REFERENCES party (tenant, id),
  FOREIGN KEY (tenant, agreement) REFERENCES agreement (tenant, id)
);

CREATE TABLE settlement_source (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "book" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "unit" TEXT NOT NULL,
  "quantity" INTEGER NOT NULL,
  "occurred_at" TEXT NOT NULL,
  "fulfillment_end" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, book) REFERENCES settlement_book (tenant, id),
  FOREIGN KEY (tenant, fulfillment_end) REFERENCES fulfillment_end (tenant, id)
);

CREATE TABLE realization (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "pin" TEXT NOT NULL,
  "build_hash" TEXT NOT NULL,
  "manifest_digest" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, pin) REFERENCES specification_pin (tenant, id)
);

CREATE TABLE repository (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "provider" TEXT NOT NULL,
  "locator" TEXT NOT NULL,
  "version" INTEGER NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE specification_pin (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "repository" TEXT NOT NULL,
  "anchor" TEXT NOT NULL,
  "revision" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, repository) REFERENCES repository (tenant, id)
);

CREATE TABLE usage_correction (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "event" TEXT NOT NULL,
  "replacement" TEXT,
  "reason" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, event) REFERENCES usage_event (tenant, id),
  FOREIGN KEY (tenant, replacement) REFERENCES usage_event (tenant, id)
);

CREATE TABLE usage_dimension (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "unit" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE usage_event (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "stream" TEXT NOT NULL,
  "dimension" TEXT NOT NULL,
  "unit" TEXT NOT NULL,
  "quantity" INTEGER NOT NULL,
  "ordinal" INTEGER NOT NULL,
  "source" TEXT NOT NULL,
  "event_key" TEXT NOT NULL,
  "occurred_at" TEXT,
  "interval_start" TEXT,
  "interval_end" TEXT,
  "replacement_for" TEXT,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, stream) REFERENCES usage_stream (tenant, id),
  FOREIGN KEY (tenant, dimension) REFERENCES usage_dimension (tenant, id),
  FOREIGN KEY (tenant, source) REFERENCES usage_source (tenant, id),
  FOREIGN KEY (tenant, replacement_for) REFERENCES usage_event (tenant, id)
);

CREATE TABLE usage_source (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE usage_stream (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  "dimension" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, dimension) REFERENCES usage_dimension (tenant, id)
);

